package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;

/**
 * Step of {@code POST /api/owners} that rejects a supplied registration date in the future. Runs
 * only WHEN a registrationDate is present: an owner created without one defaults to the server date
 * later (see {@link DetermineRegistrationDate}), so absence is accepted unchanged.
 *
 * <p>When present, the raw supplied date must not be later than the server's current date. A future
 * date is rejected with {@link FutureRegistrationDateException} (400). This runs before
 * {@link DetermineRegistrationDate}, so the check applies to the value the client sent, not the
 * business-day-adjusted date.
 */
public class RequireNotFutureRegistrationDate {

    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
        LocalDate date = request.getRegistrationDate();
        if (date != null && date.isAfter(LocalDate.now())) {
            throw new FutureRegistrationDateException(date);
        }
    }
}

===== DetermineRegistrationDate.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Step of {@code POST /api/owners} that fixes the EFFECTIVE registration date for the create —
 * the date supplied on the request, or the server's current date when none is supplied — and rolls
 * a weekend date forward to the next Monday so the registration date always falls on a business day.
 *
 * <p>Published as a variable so every later step works from the one adjusted date: the daily
 * create-limit counts owners per this business day, {@link BuildOwner} stores it, and any value
 * derived from it (such as the membership number's year segment) follows.
 */
public class DetermineRegistrationDate {

    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
        LocalDate date = request.getRegistrationDate();
        if (date == null) {
            date = LocalDate.now();
        }
        registrationDate.set(toBusinessDay(date));
    }

    /** Roll a Saturday or Sunday forward to the next Monday; a business day is unchanged. */
    static LocalDate toBusinessDay(LocalDate date) {
        DayOfWeek day = date.getDayOfWeek();
        if (day == DayOfWeek.SATURDAY) {
            return date.plusDays(2);
        }
        if (day == DayOfWeek.SUNDAY) {
            return date.plusDays(1);
        }
        return date;
    }
}

===== RequireDailyOwnerLimit.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitExceededException;

/**
 * Step of {@code POST /api/owners} that rejects a create with 429 when {@value #DAILY_LIMIT} or
 * more owners have already been registered on the same business day (by {@code registrationDate}).
 * The day counted is the effective, business-day-adjusted registration date computed by
 * {@link DetermineRegistrationDate} — the very date the new owner would be stored with — so once
 * that day is full no further owner may be created for it.
 */
public class RequireDailyOwnerLimit {

    /** Maximum number of owners that may be registered on a single day. */
    private static final int DAILY_LIMIT = 100;

    public void service(@Val LocalDate registrationDate, OwnerRepository ownerRepository)
            throws DailyOwnerLimitExceededException {
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (registrationDate.equals(existing.getRegistrationDate())) {
                count++;
            }
        }
        if (count >= DAILY_LIMIT) {
            throw new DailyOwnerLimitExceededException(registrationDate);
        }
    }
}

