package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Step of {@code POST /api/owners} that assigns the deterministic {@code householdId}. The id is
 * derived from the normalized lastName and the postcode, so any two owners with the same lastName
 * and postcode are automatically given the identical identifier and are treated as one household.
 * It is one component of the consolidated {@link OwnerIdentityKey}. The id no longer depends on
 * {@code sharesHousehold} (which now only bypasses the household duplicate block). Owners with no
 * postcode have no household and are left with no householdId.
 */
public class AssignHouseholdId {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner) {
        owner.setHouseholdId(forRequest(request));
    }

    /**
     * The householdId a create request maps to: the deterministic id for its {@code lastName} and
     * {@code postcode}, or {@code null} when no postcode is supplied (no household).
     */
    static String forRequest(OwnerFieldsDto request) {
        String postcode = request.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        return householdId(request.getLastName(), postcode);
    }

    /** Stable identifier for the household sharing {@code lastName} at {@code postcode}. */
    static String householdId(String lastName, String postcode) {
        String key = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
    }

    /** Trim, collapse internal whitespace runs to a single space, and lower-case for comparison. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    private static String sha256Hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }
}

===== AssignCustomerCode.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
 * region code derived from the postcode (see {@link OwnerLocality}) and HASH8 is the first eight
 * upper-case hex characters of SHA-256 over {@code normalizedTelephone + lastName}. The telephone
 * is normalized to E.164 (see {@link TelephoneE164}) exactly as the owner is stored, so the hash is
 * stable regardless of the telephone's input format. There are no sequence numbers: the identity is
 * fully determined by the owner's region, telephone and surname.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner) {
        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
        String normalizedTelephone = normalizedTelephone(owner.getTelephone());
        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
        owner.setCustomerCode(region + "-" + hash8);
    }

    /** The owner's telephone in the same canonical E.164 form it is stored with. */
    private static String normalizedTelephone(String telephone) {
        String e164 = TelephoneE164.toE164(telephone);
        return e164 != null ? e164 : (telephone == null ? "" : telephone);
    }

    /** First eight upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
    private static String sha256Hex8(String value) {
        byte[] digest;
        try {
            digest = MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8));
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex); // never on a standard JRE
        }
        StringBuilder sb = new StringBuilder(8);
        for (int i = 0; i < 4; i++) {
            sb.append(String.format("%02X", digest[i]));
        }
        return sb.toString().toUpperCase(Locale.ROOT);
    }
}

