package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Step of {@code POST /api/owners} that records how many existing owners already share this
 * owner's name. {@code namesakeCount} is set to the number of owners present before this create
 * whose firstName and lastName both match, compared case-insensitively with collapsed whitespace.
 * Runs before {@link SaveOwner}, so the owner being created is not counted against itself.
 */
public class AssignNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = normalize(owner.getFirstName());
        String lastName = normalize(owner.getLastName());
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (firstName.equals(normalize(existing.getFirstName()))
                    && lastName.equals(normalize(existing.getLastName()))) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    /** Trim, collapse internal whitespace runs to a single space, and lower-case for comparison. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

===== AssignHouseholdSize.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Step of {@code POST /api/owners} that records how many owners belong to this owner's household
 * once this create completes. {@code householdSize} is the number of existing owners that already
 * share this owner's {@code householdId} plus one for the owner being created. Runs after
 * {@link AssignHouseholdId} (so the householdId is set) and before {@link SaveOwner} (so the owner
 * being created is not yet in the store and is counted exactly once via the {@code + 1}). Owners
 * with no householdId are a household of one.
 */
public class AssignHouseholdSize {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        int size = 1;
        if (householdId != null) {
            for (Owner existing : ownerRepository.findAll()) {
                if (householdId.equals(existing.getHouseholdId())) {
                    size++;
                }
            }
        }
        owner.setHouseholdSize(size);
    }
}

===== AssignBulkSignupWarning.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Step of {@code POST /api/owners} that flags a bulk signup. {@code bulkSignupWarning} is set to
 * {@code true} when, at the moment this owner is created, more than {@value #BULK_THRESHOLD} owners
 * have already been created for the same registration day (by the effective, business-day-adjusted
 * {@code registrationDate} from {@link DetermineRegistrationDate}); otherwise {@code false}. Runs
 * before {@link SaveOwner}, so the owner being created is not counted against itself.
 */
public class AssignBulkSignupWarning {

    /** Owners already created today above which a bulk-signup warning is flagged. */
    private static final int BULK_THRESHOLD = 80;

    public void service(@Val Owner owner, @Val LocalDate registrationDate,
            OwnerRepository ownerRepository) {
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (registrationDate.equals(existing.getRegistrationDate())) {
                count++;
            }
        }
        owner.setBulkSignupWarning(count > BULK_THRESHOLD);
    }
}

===== AssignPossibleDuplicate.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Step of {@code POST /api/owners} that flags a soft duplicate. The create has already passed
 * {@link RequireUniqueIdentity}, so it is neither a hard identity duplicate nor an undeclared
 * household duplicate. This step marks the owner when an existing owner shares its household (the
 * same deterministic {@code householdId}, i.e. the same lastName and postcode) but has a different
 * telephone (normalized to E.164, see {@link TelephoneE164}).
 *
 * <p>A declared household member — one whose request set {@code sharesHousehold=true} — is not a
 * suspected duplicate, so it is never flagged. Otherwise, when such an owner exists,
 * {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to that owner's id — the
 * earliest (lowest-id) match when several qualify; otherwise {@code possibleDuplicate} is false and
 * {@code possibleDuplicateOf} is left unset. Runs before {@link SaveOwner}, so the owner being
 * created is not matched against itself. An owner with no household (no postcode) never soft-matches.
 */
public class AssignPossibleDuplicate {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        owner.setPossibleDuplicate(false);
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // a declared household member is not a suspected duplicate
        }
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            return;
        }
        String telephone = normalizeTelephone(owner.getTelephone());
        Owner match = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (!householdId.equals(existing.getHouseholdId())) {
                continue;
            }
            if (telephone.equals(normalizeTelephone(existing.getTelephone()))) {
                continue; // same telephone would be a hard duplicate, not a soft match
            }
            if (match == null || (existing.getId() != null && match.getId() != null
                    && existing.getId() < match.getId())) {
                match = existing;
            }
        }
        if (match != null) {
            owner.setPossibleDuplicate(true);
            owner.setPossibleDuplicateOf(match.getId());
        }
    }

    /** Canonical E.164 telephone, falling back to the raw value when it cannot be parsed. */
    private static String normalizeTelephone(String telephone) {
        String e164 = TelephoneE164.toE164(telephone);
        return e164 != null ? e164 : (telephone == null ? "" : telephone);
    }
}

