package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * The single derived key that consolidates all duplicate detection for
 * {@code POST /api/owners}. An owner's {@code identityKey} is
 * {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}; a
 * create is a duplicate — and rejected with 409 — only when a new owner's WHOLE identityKey
 * equals an existing owner's. Because the telephone is part of the key, two members of the
 * same household (same {@code householdId}) with different telephones have different keys and
 * are both allowed; only an exact full-key match collides.
 *
 * <p>Each component is normalized to the same canonical form the owner is stored with, so a
 * request and the owner it would duplicate produce identical keys regardless of input format:
 * the telephone to E.164 (see {@link TelephoneE164}), the email trimmed and lower-cased, and
 * the householdId derived exactly as {@link AssignHouseholdId} assigns it.
 */
public final class OwnerIdentityKey {

    private OwnerIdentityKey() {
    }

    /** The identityKey a create request would have once its owner is built. */
    public static String forRequest(OwnerFieldsDto request) {
        return of(request.getTelephone(), request.getEmail(), AssignHouseholdId.forRequest(request));
    }

    /** The identityKey of an already-stored owner. */
    public static String forOwner(Owner owner) {
        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    private static String of(String telephone, String email, String householdId) {
        return normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|"
                + normalizeHousehold(householdId);
    }

    private static String normalizeTelephone(String telephone) {
        String e164 = TelephoneE164.toE164(telephone);
        return e164 != null ? e164 : (telephone == null ? "" : telephone);
    }

    private static String normalizeEmail(String email) {
        if (email == null || email.isBlank()) {
            return "";
        }
        return email.trim().toLowerCase();
    }

    private static String normalizeHousehold(String householdId) {
        return householdId == null ? "" : householdId;
    }
}
===== TelephoneE164 =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes telephone numbers to E.164 form.
 *
 * <p>Rules: strip spaces, dashes and brackets; keep a leading '+' and its country code when
 * present; otherwise assume country code '+61' and drop a single leading '0' from the national
 * digits. The result is '+' followed by 8 to 15 digits, so '0412 345 678' becomes
 * '+61412345678' and '+64 21 123 456' becomes '+6421123456'.
 *
 * <p>Country-specific national-number length: '+61' requires exactly 9 national digits and '+1'
 * requires exactly 10; a number whose national part is the wrong length for its country code is
 * rejected. Other country codes are only bound by the general 8-to-15 total-digit rule.
 */
public final class TelephoneE164 {

    private TelephoneE164() {
    }

    /**
     * Converts to E.164, throwing {@link InvalidTelephoneException} when the input cannot form a
     * valid E.164 number.
     */
    public static String normalize(String input) throws InvalidTelephoneException {
        String e164 = toE164(input);
        if (e164 == null) {
            throw new InvalidTelephoneException(input);
        }
        return e164;
    }

    /**
     * Best-effort conversion to E.164; returns {@code null} when the input cannot form a valid
     * E.164 number.
     */
    public static String toE164(String input) {
        if (input == null) {
            return null;
        }
        String cleaned = input.replaceAll("[\\s\\-()]", "");
        boolean hasPlus = cleaned.startsWith("+");
        String digits = hasPlus ? cleaned.substring(1) : cleaned;
        if (digits.isEmpty() || !digits.chars().allMatch(c -> c >= '0' && c <= '9')) {
            return null;
        }
        String e164;
        if (hasPlus) {
            e164 = digits;
        }
        else {
            if (digits.startsWith("0")) {
                digits = digits.substring(1);
            }
            e164 = "61" + digits;
        }
        if (e164.length() < 8 || e164.length() > 15) {
            return null;
        }
        if (!hasValidNationalLength(e164)) {
            return null;
        }
        return "+" + e164;
    }

    /**
     * Checks the national-number length for country codes with a fixed requirement: '+61' must
     * have 9 national digits and '+1' must have 10. Any other country code passes (its length is
     * only bound by the general 8-to-15 total-digit rule).
     */
    private static boolean hasValidNationalLength(String e164) {
        if (e164.startsWith("61")) {
            return e164.length() - 2 == 9;
        }
        if (e164.startsWith("1")) {
            return e164.length() - 1 == 10;
        }
        return true;
    }
}
===== OwnerLocality =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;
import java.util.regex.Pattern;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's canonical region ({@code locality}), preferring the postcode.
 *
 * <p>The postcode range is consulted first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a
 * 4-digit postcode landing in a known range resolves the region directly. Only when the postcode
 * is absent or falls in no known range does the fixed city-to-region table apply (Sydney-&gt;NSW,
 * Melbourne-&gt;VIC, Brisbane-&gt;QLD). Anything unresolved by either is {@code "UNKNOWN"}.
 *
 * <p>Known cities keep the same region as before, but cities that share a name are disambiguated
 * by their postcode.
 */
public final class OwnerLocality {

    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");

    /** City -> canonical region (matching {@link RequirePostcode}'s table). */
    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** Region -> inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_RANGE = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    private OwnerLocality() {
    }

    /**
     * The locality of an already-stored owner: the REGION segment of its {@code customerCode}
     * identity ({@code <REGION>-<HASH8>}, see {@link AssignCustomerCode}). Falls back to deriving
     * the region straight from the postcode/city for an owner whose {@code customerCode} has not
     * been assigned or is not in the region-and-hash form.
     */
    public static String forOwner(Owner owner) {
        String code = owner.getCustomerCode();
        if (code != null) {
            int dash = code.indexOf('-');
            if (dash > 0) {
                return code.substring(0, dash);
            }
        }
        return of(owner.getCity(), owner.getPostcode());
    }

    static String of(String city, String postcode) {
        String byPostcode = regionForPostcode(postcode);
        if (byPostcode != null) {
            return byPostcode;
        }
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }

    private static String regionForPostcode(String postcode) {
        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }
}
